/// <summary>
/// Creates a new instance of the <c>METPackChangeSORepricingController</c> class.
/// </summary>
/// <returns>
/// A new <c>METPackChangeSORepricingController</c> object.
/// </returns>
public static METPackChangeSORepricingController construct()
{
    return new METPackChangeSORepricingController();
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:PackChangeSORepricing";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METPackChangeSORepricingController controller = METPackChangeSORepricingController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Validates the data contract for the sales order repricing operation.
/// Ensures that the item ID is not empty before proceeding.
/// </summary>
/// <returns>
/// true if the contract is valid and the item ID is provided; otherwise, false.
/// </returns>
protected boolean validate()
{
    DialogButton     dialogButton;
    boolean isValid = super();

    if (isValid)
    {
        METPackChangeSORepricingContract contract = this.getDataContractObject() as METPackChangeSORepricingContract;

        // Validate that the item ID is not empty
        if (contract 
            && !contract.parmItemId())
        {                             
            isValid = checkFailed(strFmt("@SYS89866", '@SYS314936'));
        }

        if(isValid)
        {
            // Show the Yes/No dialog box
            dialogButton = Box::yesNo(strFmt("@MET:PackChangeSORepricingJobWarning", contract.parmItemId()), DialogButton::No, '@MET:PackChangeSORepricing');

            // Halt processing if the user selects 'No'
            if (dialogButton == DialogButton::No)
            {
                isValid = false;
            }
        }
    }

    return isValid;
}
